/** Só as letras AB, sem moldura (como no topo das telas do carrossel). */
export const LetrasAB: React.FC<{ readonly altura: number; readonly cor?: string }> = ({
  altura,
  cor = COR.gelo,
}) => {
  const m = useMotion();
  const h = m.px(altura);
  return (
    <svg width={(h * 210) / 245} height={h} viewBox="310 330 210 245">
      <AB cor={cor} />
    </svg>
  );
};

export type MonogramaProps = {
  /** Altura em px de design. */
  readonly altura: number;
  readonly cor?: string;
  /** Anima o desenho (moldura → arcos → letras) a partir deste tempo. Omitido = estático. */
  readonly desenharEm?: number;
  /** Espessura da linha (unidades do viewBox). */
  readonly linha?: number;
};

/** Monograma AB na moldura oval. */
export const Monograma: React.FC<MonogramaProps> = ({ altura, cor = COR.gelo, desenharEm, linha = 3.6 }) => {
  const frame = useCurrentFrame();
  const m = useMotion();
  const h = m.px(altura);
  const anim = desenharEm !== undefined;
  const pLetras = anim ? progressAt(frame, m.fps, desenharEm + 0.45, 0.55, "enter") : 1;
  return (
    <svg width={h * PROPORCAO} height={h} viewBox={VIEWBOX} style={{ overflow: "visible" }}>
      {anim ? (
        <>
          <DrawPath d={PATH_MOLDURA} delay={desenharEm} duration={0.8} stroke={cor} strokeWidth={linha} />
          <DrawPath d={PATH_ARCO_1} delay={desenharEm + 0.35} duration={0.5} stroke={cor} strokeWidth={linha} />
          <DrawPath d={PATH_ARCO_2} delay={desenharEm + 0.35} duration={0.5} stroke={cor} strokeWidth={linha} />
        </>
      ) : (
        <g fill="none" stroke={cor} strokeWidth={linha} strokeLinecap="round">
          <path d={PATH_MOLDURA} />
          <path d={PATH_ARCO_1} />
          <path d={PATH_ARCO_2} />
        </g>
      )}
      <g
        style={{
          opacity: pLetras,
          transform: `scale(${interpolate(pLetras, [0, 1], [0.86, 1])})`,
          transformOrigin: "406px 450px",
          filter: pLetras < 1 ? `blur(${(1 - pLetras) * 6}px)` : undefined,
        }}
      >
        <AB cor={cor} />
      </g>
    </svg>
  );
};

/** Assinatura completa (monograma + nome + subtítulo), lado a lado como na logo. */
export const LogoCompleta: React.FC<{
  readonly altura: number;
  readonly cor?: string;
  readonly desenharEm?: number;
}> = ({ altura, cor = COR.gelo, desenharEm }) => {
  const m = useMotion();
  const t0 = desenharEm ?? -10;
  // proporções medidas no print: nome = 0,22 da altura do monograma por linha
  const nome = altura * 0.215;
  return (
    <div style={{ display: "flex", alignItems: "center", gap: m.px(altura * 0.07) }}>
      <Monograma altura={altura} cor={cor} desenharEm={desenharEm} />
      <div style={{ display: "flex", flexDirection: "column", gap: m.px(altura * 0.01) }}>
        <TextReveal
          text={"ALINE\nBARBOSA"}
          by="char"
          delay={t0 + 0.7}
          stagger={0.035}
          size={nome}
          lineHeight={0.98}
          tracking="0.005em"
          color={cor}
          align="left"
          style={{ fontFamily: FONTE_SERIFADA, fontWeight: 400 }}
        />
        <TextReveal
          text="CONTABILIDADE E"
          by="word"
          delay={t0 + 1.2}
          size={altura * 0.058}
          tracking="0.42em"
          color={cor}
          align="left"
          style={{ fontFamily: FONTE_TEXTO, fontWeight: 400, marginTop: m.px(altura * 0.035) }}
        />
        <TextReveal
          text="LEGALIZAÇÃO DE EMPRESAS"
          by="word"
          delay={t0 + 1.35}
          size={altura * 0.061}
          tracking="0.005em"
          color={cor}
          align="left"
          style={{ fontFamily: FONTE_TEXTO, fontWeight: 400 }}
        />
      </div>
    </div>
  );
};
